begin;
select no_plan();
select ok((select not enabled and daily_units_limit=800 from private.mock_basemap_config),'Mock route defaults off with conservative subcap');
select ok((select relrowsecurity from pg_class where oid='private.mock_basemap_config'::regclass),'Mock configuration RLS');
select ok(not has_table_privilege('service_role','private.mock_basemap_config','SELECT'),'Service cannot bypass bounded APIs');
select ok(not has_table_privilege('authenticated','private.mock_basemap_claims','SELECT'),'Acquisition leases are private');
select ok((select relrowsecurity from pg_class where oid='private.mock_basemap_claims'::regclass),'Acquisition lease RLS');
select ok(not has_function_privilege('anon','public.reserve_mock_basemap_tile_v1(text,text,integer,integer,integer,boolean)','execute'),'No guest reservation');
select ok(not has_function_privilege('authenticated','public.reserve_mock_basemap_tile_v1(text,text,integer,integer,integer,boolean)','execute'),'No member-asserted mock identity');
select ok(not has_function_privilege('authenticated','public.finish_mock_basemap_tile_v1(integer,integer,integer,uuid,text)','execute'),'No member finish');
select ok(not has_function_privilege('service_role','private.reserve_basemap_tile_internal_v3(uuid,text,text,integer,integer,integer,boolean)','execute'),'No internal cache/meter bypass');
select ok(not has_function_privilege('service_role','private.reserve_mock_map_provider_v1(text,text,boolean)','execute'),'No direct mock charge');
select ok(has_function_privilege('service_role','public.reserve_mock_basemap_tile_v1(text,text,integer,integer,integer,boolean)','execute'),'Narrow service reservation');
select throws_ok($$select public.reserve_mock_basemap_tile_v1(null,repeat('b',64),12,2174,1456,false)$$,'22023','Invalid mock map scope','Null actor cannot select normal path');
select throws_ok($$select public.reserve_mock_basemap_tile_v1('actor',repeat('b',64),12,2174,1456,false)$$,'22023','Invalid mock map scope','No arbitrary actor scope');
select throws_ok($$select public.reserve_mock_basemap_tile_v1(repeat('a',64),repeat('b',64),19,1,1,false)$$,'22023','Invalid basemap tile.','Mock shares zoom bound');
select throws_ok($$update private.mock_basemap_config set daily_units_limit=2001$$,'23514',null,'No independently raised mock allowance');
insert into auth.users(id,email) values('a9540000-0000-4000-8000-000000000001','mapmock-normal@planets.invalid');
insert into public.profiles(id,display_name) values('a9540000-0000-4000-8000-000000000001','Normal map actor');
delete from private.location_provider_usage;
delete from private.map_baseline_tiles;
delete from private.map_provider_cache where kind='tile';
update private.location_provider_config set enabled=true,tiles_enabled=true,cache_license_approved=true,tile_cache_seconds=60,daily_units_limit=8000,actor_daily_units=8000,actor_minute_requests=120,global_minute_requests=600,failure_streak=0,blocked_until=null;
update private.map_baseline_config set enabled=true,license_approved=true;
select is(public.reserve_mock_basemap_tile_v1(repeat('a',64),repeat('b',64),12,2174,1456,true)->>'status','disabled','Independent mock kill precedes cache lookup');
update private.mock_basemap_config set enabled=true;
select is(public.reserve_mock_basemap_tile_v1(repeat('a',64),repeat('b',64),12,2174,1456,true)->>'status','cache_miss','No cache-only acquisition');
select is((select count(*) from private.location_provider_usage where scope='units:global'),0::bigint,'Cache-only spends zero units');
select set_config('test.mapmock.claim',public.reserve_mock_basemap_tile_v1(repeat('a',64),repeat('b',64),12,2174,1456,false)::text,true);
select is(current_setting('test.mapmock.claim')::jsonb->>'cached','false','Cold mock acquisition without normal profile');
select is(public.reserve_basemap_tile_v2('a9540000-0000-4000-8000-000000000001',12,2174,1456,false)->>'status','pending','Normal caller coalesces mock pending tile');
select is((select used from private.location_provider_usage where scope='units:global'),1,'One global quarter unit');
select is((select used from private.location_provider_usage where scope='units:mock'),1,'Same unit also consumes mock subcap');
select is((select count(*) from private.location_provider_usage where scope like 'units:actor:%'),0::bigint,'No fictitious normal profile actor');
update private.mock_basemap_config set max_concurrent_tiles=1;
select is(public.reserve_mock_basemap_tile_v1(repeat('a',64),repeat('b',64),18,2003,2001,false)->>'status','pending','Server IO concurrency bound applies before another acquisition');
select is((select used from private.location_provider_usage where scope='units:global'),1,'Concurrency refusal never charges');
select is((select count(*) from private.mock_basemap_claims),1::bigint,'Only the pending acquisition owns a lease');
update private.mock_basemap_config set max_concurrent_tiles=6;
select is(public.finish_mock_basemap_tile_v1(12,2174,1456,(current_setting('test.mapmock.claim')::jsonb->>'token')::uuid,
 encode(decode('89504e470d0a1a0a0000000d4948445200000100000001000806000000000000000000000049454e44ae426082','hex'),'base64'))->>'status','ok','SQL header fixture finishes shared baseline');
select is((select count(*) from private.mock_basemap_claims),0::bigint,'Finish releases the server IO slot');
select is(public.finish_mock_basemap_tile_v1(12,2174,1456,(current_setting('test.mapmock.claim')::jsonb->>'token')::uuid)->>'status','expired','Replay cannot finish or charge twice');
select is(public.reserve_basemap_tile_v2('a9540000-0000-4000-8000-000000000001',12,2174,1456,false)->>'cached','true','Normal consumes identical public cache entry');
update private.mock_basemap_config set daily_units_limit=1;
select is(public.reserve_mock_basemap_tile_v1(repeat('a',64),repeat('b',64),14,8698,5824,false)->'source'->>'z','12','Mock subcap returns real ancestor source identity');
select is(public.reserve_mock_basemap_tile_v1(repeat('a',64),repeat('b',64),14,8698,5824,false)->>'budget_exhausted','true','Subcap preserves budget metadata');
select is(public.reserve_mock_basemap_tile_v1(repeat('a',64),repeat('b',64),18,2001,2001,false)->>'status','budget_exhausted','Mock subcap blocks cold unrelated geography');
select is((select used from private.location_provider_usage where scope='units:global'),1,'Fallback has no unseen charges');
select is(public.reserve_basemap_tile_v2('a9540000-0000-4000-8000-000000000001',18,2001,2001,false)->>'status','ok','Ordinary allowance survives mock subcap');
select is((select used from private.location_provider_usage where scope='units:global'),2,'Normal and mock use the very same counter');
update private.mock_basemap_config set daily_units_limit=800,actor_daily_units=1;
select is(public.reserve_mock_basemap_tile_v1(repeat('a',64),repeat('c',64),18,2002,2001,false)->>'status','budget_exhausted','New clients cannot evade shared-persona actor cap');
update private.mock_basemap_config set actor_daily_units=120,client_daily_units=1;
select is(public.reserve_mock_basemap_tile_v1(repeat('c',64),repeat('b',64),18,2002,2001,false)->>'status','budget_exhausted','Changing persona cannot evade client cap');
update private.mock_basemap_config set client_daily_units=160,actor_minute_requests=1;
select is(public.reserve_mock_basemap_tile_v1(repeat('a',64),repeat('b',64),12,2174,1456,true)->>'status','rate_limited','Cached public pixels still consume request rate');
update private.mock_basemap_config set actor_minute_requests=24,client_minute_requests=1;
select is(public.reserve_mock_basemap_tile_v1(repeat('c',64),repeat('b',64),12,2174,1456,true)->>'status','rate_limited','Client cache-hit minute rate');
update private.mock_basemap_config set client_minute_requests=36,aggregate_minute_requests=1;
select is(public.reserve_mock_basemap_tile_v1(repeat('c',64),repeat('c',64),12,2174,1456,true)->>'status','rate_limited','Aggregate cap survives new identities');
update private.mock_basemap_config set aggregate_minute_requests=60;
update private.location_provider_config set blocked_until=statement_timestamp()+interval '30 seconds';
select is(public.reserve_mock_basemap_tile_v1(repeat('a',64),repeat('b',64),12,2174,1456,true)->>'status','unavailable','Shared circuit also protects cache reads');
update private.location_provider_config set blocked_until=null,enabled=false;
select is(public.reserve_mock_basemap_tile_v1(repeat('a',64),repeat('b',64),12,2174,1456,true)->>'status','disabled','Master kills mock cache');
update private.location_provider_config set enabled=true;
update private.mock_basemap_config set enabled=false;
select is(public.reserve_mock_basemap_tile_v1(repeat('a',64),repeat('b',64),12,2174,1456,true)->>'status','disabled','Mock kill blocks cache while ordinary remains enabled');
select is(public.reserve_basemap_tile_v2('a9540000-0000-4000-8000-000000000001',12,2174,1456,true)->>'status','ok','Normal cache survives mock-only kill');
select * from finish();
rollback;
